private theorem native_rest_rows (p : Fin 4 → ℂ) (v : Fin 289 → ℂ) :
    emRestSlice (emOriginalJacobi p*ᵥv)=
      nativeRestRest p*ᵥemRestSlice v+nativeRestAuxiliary p*ᵥemAuxiliarySlice v

private theorem native_auxiliary_rows (p : Fin 4 → ℂ) (v : Fin 289 → ℂ) :
    emAuxiliarySlice (emOriginalJacobi p*ᵥv)=nativeAuxiliaryRest p*ᵥemRestSlice v+
      originalGaugeAuxiliaryPencil p*ᵥemAuxiliarySlice v

private theorem observed_em_forcing (p : Fin 4 → ℂ) (nu : Fin 4) :
    nativeEMRestInsertion.transpose*ᵥnativeCompleteForceRead p (fun i => emInsertion i nu)=
      (3/4 : ℂ) • Pi.single nu 1
